**package.json**
```json
{
  "name": "kube-toolkit",
  "version": "1.0.0",
  "description": "A comprehensive npm CLI toolkit for Kubernetes",
  "main": "index.js",
  "scripts": {
    "start": "node index.js"
  },
  "keywords": [],
  "author": "",
  "license": "MIT",
  "dependencies": {
    "@kubernetes/client-node": "^0.15.0",
    "axios": "^0.21.1",
    "chalk": "^4.1.2",
    "fs-extra": "^10.0.0",
    "inquirer": "^8.2.4",
    "lodash": "^4.17.21",
    "ora": "^5.4.1"
  },
  "bin": {
    "kube-toolkit": "index.js"
  }
