```

**index.js**
```javascript
#!/usr/bin/env node

const { Command } = require('commander');
const program = new Command();
const axios = require('axios');
const fs = require('fs-extra');
const path = require('path');
const inquirer = require('inquirer');
const chalk = require('chalk');
const ora = require('ora');
const { KubeConfig, CoreV1Api, RbacAuthorizationV1Api, NetworkingV1Api, AppsV1Api } = require('@kubernetes/client-node');

const kubeConfig = new KubeConfig();
kubeConfig.loadFromDefault();

const coreV1Api = kubeConfig.makeApiClient(CoreV1Api);
const rbacV1Api = kubeConfig.makeApiClient(RbacAuthorizationV1Api);
const networkingV1Api = kubeConfig.makeApiClient(NetworkingV1Api);
const appsV1Api = kubeConfig.makeApiClient(AppsV1Api);

program
  .version('1.0.0')
  .description('A comprehensive npm CLI toolkit for Kubernetes');

program
  .command('cluster-health')
  .description('Monitor cluster health')
  .action(async () => {
    const spinner = ora('Checking cluster health...').start();
    try {
      const nodes = await coreV1Api.listNode();
      const pods = await coreV1Api.listPodForAllNamespaces();
      console.log(chalk.green('Cluster health:'));
      console.log(`Nodes: ${nodes.body.items.length}`);
      console.log(`Pods: ${pods.body.items.length}`);
      spinner.succeed();
    } catch (error) {
      spinner.fail();
      console.error(chalk.red(error));
    }
  });

program
  .command('pod-logs')
  .description('Aggregate pod logs')
  .action(async () => {
    const spinner = ora('Aggregating pod logs...').start();
    try {
      const pods = await coreV1Api.listPodForAllNamespaces();
      const logs = await Promise.all(pods.body.items.map(async (pod) => {
        const log = await coreV1Api.readNamespacedPodLog(pod.metadata.name, pod.metadata.namespace);
        return log.body;
      }));
      console.log(chalk.green('Pod logs:'));
