To use this CLI toolkit, save the `package.json` and `index.js` files to a directory, navigate to that directory in your terminal, and run the following command:
```bash
npm install
```
This will install the dependencies required by the CLI toolkit. Once the dependencies are installed, you can use the CLI toolkit by running the following command:
```bash
node index.js --help
```
This will display the available commands and options for the CLI toolkit. You can then use the individual commands to perform the desired actions. For example, to monitor cluster health, you can run the following command:
```bash
node index.js cluster-health
```

Below is a complete Terraform module that sets up a production EKS cluster with the specified components. This module uses Terraform 1.0+ and assumes you have the necessary AWS credentials configured.

**File Structure:**
```markdown
eks-production/
├── main.tf
├── variables.tf
├── outputs.tf
├── vpc.tf
├── eks.tf
├── node_groups.tf
├── karpenter.tf
├── alb_controller.tf
├── external_dns.tf
├── cert_manager.tf
├── argocd.tf
├── prometheus_grafana.tf
├── cost_optimization_lambda.tf
└── versions.tf
```

**versions.tf:**
```terraform
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.0.0"
    }
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = ">= 2.0.0"
    }
  }
}
```

**variables.tf:**
```terraform
variable "region" {
  type        = string
  default     = "us-west-2"
  description = "AWS Region"
}

variable "cluster_name" {
  type        = string
  default     = "eks-production"
  description = "EKS Cluster Name"
}

variable "vpc_cidr" {
  type        = string
  default     = "10.0.0.0/16"
  description = "VPC CIDR Block"
}

variable "availability_zones" {
  type        = list(string)
  default     = ["us-west-2a", "us-west-2b", "us-west-2c"]
  description = "Availability Zones"
}

variable "instance_types" {
  type        = list(string)
  default     = ["t3.medium", "t3.large"]
  description = "Instance Types for Node Groups"
}

variable "spot_instance_types" {
  type        = list(string)
  default     = ["t3.medium", "t3.large"]
  description = "Spot Instance Types for Node Groups"
}

variable "node_group_desired_capacity" {
  type        = number
  default     = 3
  description = "Desired Capacity for Node Groups"
}

variable "node_group_max_capacity" {
  type        = number
  default     = 6
  description = "Max Capacity for Node Groups"
}

variable "node_group_min_capacity" {
  type        = number
  default     = 1
  description = "Min Capacity for Node Groups"
}
```

**main.tf:**
```terraform
provider "aws" {
  region = var.region
}

module "vpc" {
  source = "./vpc.tf"

  cidr_block = var.vpc_cidr
  availability_zones = var.availability_zones
}

module "eks" {
  source = "./eks.tf"

  cluster_name = var.cluster_name
  vpc_id       = module.vpc.vpc_id
  subnets      = module.vpc.subnets
}

module "node_groups" {
  source = "./node_groups.tf"

  cluster_name    = var.cluster_name
  instance_types  = var.instance_types
  spot_instance_types = var.spot_instance_types
  node_group_desired_capacity = var.node_group_desired_capacity
  node_group_max_capacity     = var.node_group_max_capacity
  node_group_min_capacity     = var.node_group_min_capacity
  vpc_id       = module.vpc.vpc_id
  subnets      = module.vpc.subnets
}

module "karpenter" {
  source = "./karpenter.tf"

  cluster_name = var.cluster_name
  vpc_id       = module.vpc.vpc_id
  subnets      = module.vpc.subnets
}

module "alb_controller" {
  source = "./alb_controller.tf"

  cluster_name = var.cluster_name
  vpc_id       = module.vpc.vpc_id
  subnets      = module.vpc.subnets
}

module "external_dns" {
  source = "./external_dns.tf"

  cluster_name = var.cluster_name
  vpc_id       = module.vpc.vpc_id
  subnets      = module.vpc.subnets
}

module "cert_manager" {
  source = "./cert_manager.tf"

  cluster_name = var.cluster_name
  vpc_id       = module.vpc.vpc_id
  subnets      = module.vpc.subnets
}

module "argocd" {
  source = "./argocd.tf"

  cluster_name = var.cluster_name
  vpc_id       = module.vpc.vpc_id
  subnets      = module.vpc.subnets
}

module "prometheus_grafana" {
  source = "./prometheus_grafana.tf"

  cluster_name = var.cluster_name
  vpc_id       = module.vpc.vpc_id
  subnets      = module.vpc.subnets
}

module "cost_optimization_lambda" {
  source = "./cost_optimization_lambda.tf"

  cluster_name = var.cluster_name
  vpc_id       = module.vpc.vpc_id
  subnets      = module.vpc.subnets
}
```

**vpc.tf:**
```terraform
resource "aws_vpc" "this" {
  cidr_block = var.cidr_block
  tags = {
    Name = "eks-vpc"
  }
}

resource "aws_subnet" "this" {
  count = length(var.availability_zones)

  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(aws_vpc.this.cidr_block, 8, count.index)
  availability_zone = var.availability_zones[count.index]
  tags = {
    Name = "eks-subnet-${count.index}"
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id
  tags = {
    Name = "eks-igw"
  }
}

resource "aws_eip" "this" {
  count = length(var.availability_zones)
  vpc   = true
  tags = {
    Name = "eks-eip-${count.index}"
  }
}

resource "aws_nat_gateway" "this" {
  count = length(var.availability_zones)

  allocation_id = aws_eip.this[count.index].id
  subnet_id     = aws_subnet.this[count.index].id
  tags = {
    Name = "eks-nat-gw-${count.index}"
  }
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "subnets" {
  value = aws_subnet.this.*.id
}
```

**eks.tf:**
```terraform
